<script setup lang="ts">
import {ref,computed,onMounted,watch} from 'vue';import {useWorkbench} from '../stores/workbench';import {fmt,api} from '../api/client';import EChart from './EChart.vue';import DaliMap from './DaliMap.vue';import StatusBadge from './StatusBadge.vue';import UiIcon from './UiIcon.vue';const s=useWorkbench(),tab=ref('geography'),period=ref(1),meshedOnly=ref(false),search=ref(''),selected=ref<any>(null),topoChart=ref<any>(),matrixAll=ref(false),kvFilter=ref('all'),genIds=ref<string[]>([]),genMeta=ref<Record<string,any>>({});const mock=computed(()=>!s.results?.result||s.results.result.status==='mock'),result=computed(()=>s.results?.result||{}),base=computed(()=>s.results?.baseline||{});const at=(v:any,t=period.value)=>Array.isArray(v)?v[t-1]:v;const c=(name:string)=>getComputedStyle(document.documentElement).getPropertyValue(name).trim();function baseline(id:string,key:string){return at(base.value[key]?.[id]);}function status(link:any){return mock.value?Number(link.BR_STATUS??1):Number(at(result.value.branch_status?.[link.id])??link.BR_STATUS??1);}function loading(link:any){const f=result.value.branch_flow?.[link.id];if(!mock.value&&f&&Number(link.RATE_A)>0)return Math.max(Math.hypot(at(f.pf)||0,at(f.qf)||0),Math.hypot(at(f.pt)||0,at(f.qt)||0))/link.RATE_A;return link.loading||0;}
const graph=computed(()=>{const links=(s.topology?.links||[]).filter((l:any)=>!meshedOnly.value||!l.is_bridge);const ids=new Set(links.flatMap((l:any)=>[l.source,l.target]));const palette:Record<string,string>={'500':c('--amber'),'220':c('--primary'),'110':c('--blue'),'35':c('--accent'),'10':c('--faint'),'6':c('--muted')};const found=links.find((l:any)=>l.id===search.value.toUpperCase());return {tooltip:{trigger:'item',confine:true,formatter:(p:any)=>p.dataType==='edge'?p.data.id+' · '+p.data.source+'—'+p.data.target+'<br/>电压 '+p.data.kv+' kV · '+(p.data.off?'停运':'在运'):p.data.id+' · '+p.data.kv+' kV'},animation:false,series:[{type:'graph',layout:'none',roam:true,edgeSymbol:['none','none'],data:(s.topology?.nodes||[]).filter((n:any)=>!meshedOnly.value||ids.has(n.id)).map((n:any)=>({...n,name:n.id,symbolSize:n.kv>=220?8:n.kv>=110?6:4,label:{show:search.value.toUpperCase()===n.id||found?.source===n.id||found?.target===n.id,position:'right',color:palette[n.kv]||c('--primary')},itemStyle:{color:palette[n.kv]||c('--faint'),borderColor:c('--primary-deep'),borderWidth:search.value.toUpperCase()===n.id?3:0}})),links:links.map((l:any)=>({...l,name:l.id,off:status(l)===0,lineStyle:{color:status(l)===0?c('--muted'):loading(l)>=1?c('--danger'):loading(l)>=.8?c('--amber'):c('--primary'),opacity:l.id===search.value.toUpperCase()?1:l.is_bridge?.25:.55,width:l.id===search.value.toUpperCase()?4:l.is_bridge?.6:1.3,type:status(l)===0?'dashed':'solid'}})),emphasis:{focus:'adjacency',lineStyle:{width:3}}}]};});
function locate(){const q=search.value.toUpperCase().trim();search.value=q;selected.value=(s.topology?.nodes||[]).find((n:any)=>n.id===q)||(s.topology?.links||[]).find((n:any)=>n.id===q)||{id:q,message:'未找到此编号，请核对原始数据。'};topoChart.value?.focus(q);}
function onSelect(p:any){selected.value=p.data;search.value=p.data.id}
const matrixRows=computed(()=>{if(mock.value)return [];return(s.topology?.links||[]).filter((l:any)=>kvFilter.value==='all'||String(l.kv)===kvFilter.value).filter((l:any)=>matrixAll.value?!l.is_bridge:Array.from({length:16},(_,i)=>at(result.value.branch_status?.[l.id],i+1)??l.BR_STATUS).some(x=>Number(x)!==Number(l.BR_STATUS))).map((l:any)=>({id:l.id,label:l.source+'–'+l.target,kv:l.kv,values:Array.from({length:16},(_,i)=>at(result.value.branch_status?.[l.id],i+1)??l.BR_STATUS)}))});
const availableGens=computed(()=>Object.keys(result.value.gen_p||{}).sort((a,b)=>Math.max(...result.value.gen_p[b].map((v:number,i:number)=>Math.abs(v-(at(base.value.gen_p?.[b],i+1)||0))))-Math.max(...result.value.gen_p[a].map((v:number,i:number)=>Math.abs(v-(at(base.value.gen_p?.[a],i+1)||0))))));
const generation=computed(()=>({tooltip:{trigger:'axis'},legend:{type:'scroll',bottom:0,textStyle:{fontSize:parseFloat(c('--font-xs'))}},grid:{top:25,left:55,right:25,bottom:70},xAxis:{type:'category',name:'时段',data:Array.from({length:16},(_,i)=>i+1)},yAxis:{type:'value',name:'MW',scale:true},series:genIds.value.filter(id=>result.value.gen_p?.[id]).flatMap(id=>[{name:id+' 调整后',type:'line',data:result.value.gen_p[id].map((v:number)=>({value:v,itemStyle:{color:genMeta.value[id]&&(v>genMeta.value[id].PMAX||v<genMeta.value[id].PMIN)?c('--danger'):undefined}})),symbolSize:6},{name:id+' 调整前',type:'line',data:Array.from({length:16},(_,i)=>at(base.value.gen_p?.[id],i+1)),lineStyle:{type:'dashed',opacity:.5},symbol:'none'}])}));
const diffs=computed(()=>{if(mock.value)return [];const out:any[]=[];for(const k of ['branch_status','gen_p','bus_vm'])for(const [id,arr]of Object.entries(result.value[k]||{})){(arr as number[]).forEach((v,i)=>{const b=at(base.value[k]?.[id],i+1);if(b!==undefined&&Math.abs(v-b)>1e-8)out.push({id,param:k==='branch_status'?'开断状态':k==='gen_p'?'有功出力 / MW':'电压 / p.u.',period:i+1,before:b,after:v,delta:v-b})})}for(const [id,flow]of Object.entries(result.value.branch_flow||{}))for(const [key,arr]of Object.entries(flow as any)){if(!Array.isArray(arr))continue;(arr as number[]).forEach((v,i)=>{const old=at(base.value.branch_flow?.[id]?.[key],i+1);if(old!==undefined&&Math.abs(v-old)>1e-8)out.push({id,param:({pf:'首端有功 / MW',qf:'首端无功 / Mvar',pt:'末端有功 / MW',qt:'末端无功 / Mvar'} as any)[key]||key,period:i+1,before:old,after:v,delta:v-old})})}return out});
watch(genIds,async ids=>{await Promise.all(ids.filter(id=>!genMeta.value[id]).map(async id=>{try{const x=await api('/objects?type=gen&q='+encodeURIComponent(id));const item=(x.items||[]).find((o:any)=>o.id===id);if(item)genMeta.value[id]=item;}catch{}}))},{deep:true});onMounted(async()=>{try{await s.loadResults();genIds.value=availableGens.value.slice(0,10)}catch(e:any){s.error=e.message}});
</script><template><div class="content-pad"><div class="panel-heading"><div><div class="eyebrow">M6 / 方案与网架</div><h2>地理场景与电网结果</h2></div><el-button type="primary" :loading="s.busy" @click="s.evaluate().catch(()=>{})" data-testid="go-risk">评估指标与风险 <UiIcon name="arrow" :size="15"/></el-button></div><div v-if="mock" class="notice amber"><UiIcon name="info"/><span>黑盒占位：未调用求解器。以下为真实基态，尚无调整后方案或出力曲线。</span></div><div v-else class="notice"><span>外部导入结果 · {{result.solver}} · {{result.status}}。结果身份由提供方报告，工作台已检查字段和维度。</span></div><el-tabs v-model="tab"><el-tab-pane label="大理地理图" name="geography"><DaliMap v-if="tab==='geography'"/><p class="geo-context-note">地理底图用于展示大理区域。当前合成演示断面没有设备经纬度；905 节点的连通关系请切换“电气拓扑”查看。</p></el-tab-pane><el-tab-pane label="电气拓扑" name="topology"><div class="toolbar graph-toolbar"><div class="actions"><el-switch v-model="meshedOnly" active-text="只看网状部分"/><span class="small-note">{{meshedOnly?((s.topology?.links||[]).filter((l:any)=>!l.is_bridge).length+' 条网状支路'):(s.topology?.nodes?.length||0)+' 节点 · '+(s.topology?.links?.length||0)+' 支路'}}</span></div><div class="graph-search"><el-input v-model="search" placeholder="搜索 B43 / L155" @keyup.enter="locate" clearable/><el-button @click="locate">定位</el-button></div></div><div class="topology-wrap"><EChart ref="topoChart" :option="graph" height="500px" @select="onSelect"/><div class="graph-legend"><span v-for="v in [500,220,110,35,10,6]" :key="v"><i :class="'kv-'+v"></i>{{v}} kV</span></div><div v-if="selected" class="graph-detail"><div class="section-heading"><strong>{{selected.id}}</strong><button class="text-button" @click="selected=null">×</button></div><p v-if="selected.message">{{selected.message}}</p><template v-else><p>{{selected.kv}} kV <span v-if="selected.source">· {{selected.source}}—{{selected.target}}</span></p><div class="key-value" v-if="selected.source"><span>热稳限额</span><strong>{{fmt(selected.RATE_A)}} MVA</strong><span>原始有功潮流</span><strong>{{fmt(selected.PF)}} MW</strong><span>孤岛型支路</span><strong>{{selected.is_bridge?'是':'否'}}</strong></div><div class="key-value" v-else><span>原始电压</span><strong>{{fmt(selected.VM,4)}} p.u.</strong><span>有功负荷</span><strong>{{fmt(selected.PD)}} MW</strong></div></template></div></div><div class="period-slider"><span>{{mock?'断面展示':'结果时段'}} {{period}} / 16</span><el-slider v-model="period" :min="1" :max="16" show-stops/><span class="small-note">虚线：停运 · 细线：孤岛型 · 橙：重载 · 红：越限</span></div></el-tab-pane><el-tab-pane label="开断矩阵" name="switching"><div v-if="mock" class="inline-empty large">Mock 模式未产生开断方案。</div><template v-else><div class="toolbar"><el-switch v-model="matrixAll" active-text="显示全部可开断支路"/><el-select v-model="kvFilter" class="compact-select"><el-option label="全部电压等级" value="all"/><el-option v-for="v in [500,220,110,35]" :key="v" :value="String(v)" :label="v+' kV'"/></el-select></div><div v-if="matrixRows.length" class="matrix-scroll"><table class="switching-matrix"><thead><tr><th>支路 / 时段</th><th v-for="n in 16" :key="n">{{n}}</th></tr></thead><tbody><tr v-for="row in matrixRows" :key="row.id"><th>{{row.id}} <small>{{row.kv}} kV</small></th><td v-for="(v,i) in row.values" :key="i" :class="{open:v===0}"><span>{{v===0?'断':'合'}}</span></td></tr></tbody></table></div><el-empty v-else description="导入结果未报告开断状态变化。"/></template></el-tab-pane><el-tab-pane label="机组出力" name="generation"><div v-if="mock||!availableGens.length" class="inline-empty large">尚无可展示的优化后机组出力。请导入包含 gen_p 的真实结果。</div><template v-else><el-select v-model="genIds" multiple filterable collapse-tags collapse-tags-tooltip class="full-width" placeholder="选择机组"><el-option v-for="id in availableGens" :key="id" :value="id" :label="id"/></el-select><EChart :option="generation" height="420px"/><p class="small-note">默认按出力调整量排序显示前 10 台。实线为导入结果，虚线为调整前断面；越界点标红。</p></template></el-tab-pane><el-tab-pane label="前后差异" name="comparison"><el-table v-if="diffs.length" :data="diffs" height="450" stripe><el-table-column prop="id" label="对象" width="100"/><el-table-column prop="param" label="参数"/><el-table-column prop="period" label="时段" width="80"/><el-table-column label="调整前"><template #default="{row}">{{fmt(row.before,4)}}</template></el-table-column><el-table-column label="调整后"><template #default="{row}">{{fmt(row.after,4)}}</template></el-table-column><el-table-column label="差值"><template #default="{row}">{{fmt(row.delta,4)}}</template></el-table-column></el-table><el-empty v-else :description="mock?'当前没有调整后结果可比对。':'导入结果与断面没有可比较的差异项。'"/></el-tab-pane></el-tabs><div class="panel-bottom-actions"><span class="small-note">固定种子拓扑布局 · 支持缩放、拖动与对象详情</span><el-tooltip content="需课题 2 提供测点与设备动作映射"><span class="disabled-action">结果回写测点 <StatusBadge name="结果回写测点"/></span></el-tooltip></div></div></template>